const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (Object.keys(j).length === 0) continue;
  const clean = {};
  for (const k of Object.keys(j)) {
    const key = String(k).trim();
    let v = j[k];
    if (typeof v === 'string') v = v.trim();
    clean[key] = v;
  }
  rows.push(clean);
}
const totalRows = rows.length;
const columns = totalRows > 0 ? Object.keys(rows[0]) : [];
const model = totalRows > 400 ? 'gpt-5.6-luna' : 'gpt-5-mini';
const capped = rows.slice(0, 800);
return [{ json: {
  totalRows,
  rowsIncluded: capped.length,
  columns,
  model,
  datasetText: JSON.stringify(capped),
} }];

const o = $json.output || $json || {};
const clean = $('Clean & Route').first().json || {};
let question = '';
try { question = $('When chat message received').first().json.chatInput || ''; } catch (e) {}
const primary = o.primary_agent || 'none';
const secondary = Array.isArray(o.secondary_agents) ? o.secondary_agents : [];
const selected = new Set([primary].concat(secondary).filter(function (a) { return a && a !== 'none'; }));
let responseType = o.response_type || (o.needs_clarification ? 'clarify' : (primary === 'none' ? 'conversational' : 'route'));
if (responseType === 'route' && selected.size === 0) responseType = 'conversational';
return [{ json: {
  orchestrator: o,
  response_type: responseType,
  primary_agent: primary,
  secondary_agents: secondary,
  intent_summary: o.intent_summary || '',
  clarifying_question: o.clarifying_question || '',
  routing_rationale: o.routing_rationale || '',
  suggested_filters: o.suggested_filters || {},
  question: question,
  run_sourcing: selected.has('sourcing_quality'),
  run_rejection: selected.has('rejection_pattern'),
  run_panel: selected.has('panel_load_balancer'),
  run_offer: selected.has('offer_insights'),
  run_pipeline: selected.has('pipeline_health'),
  totalRows: clean.totalRows,
  rowsIncluded: clean.rowsIncluded,
  columns: clean.columns,
  model: clean.model,
  datasetText: clean.datasetText,
} }];

const j = $json || {};
let msg = '';
if (j.response_type === 'clarify') {
  msg = j.clarifying_question || 'Could you clarify which hiring area you need insight on (sourcing, rejections, panel load, offers, or pipeline health)?';
} else {
  msg = 'Hi! I am HireFast AI. I can help with sourcing quality, rejection patterns, interviewer panel load, offer declines, and pipeline health. What would you like to know?';
}
return [{ json: { chat_message: msg, response_type: j.response_type } }];

const asText = (v) => (typeof v === 'string' ? v : JSON.stringify(v));
const num = (v) => (v === null || v === undefined || v === '' ? '' : (isNaN(Number(v)) ? v : Number(v)));
function readable(v, depth) {
  depth = depth || 0;
  if (v === null || v === undefined) return '';
  if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return v.map(function (x) { return readable(x, depth + 1); }).join(depth > 0 ? '; ' : ' | ');
  return Object.keys(v).map(function (k) { return k + ': ' + readable(v[k], depth + 1); }).join('; ');
}
let question = '';
try { question = $('Build Routing').first().json.question || ''; } catch (e) {}
const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error || j.__error) continue; // skip agent error passthrough items
  const o = j.output ? j.output : j;
  if (!o || (!o.agent && !o.recommendation)) continue; // only real agent outputs
  const cost = (o.cost_of_insight && typeof o.cost_of_insight === 'object') ? o.cost_of_insight : {};
  out.push({ json: {
    execution_id: $execution.id,
    question: question,
    agent: o.agent || '',
    recommendation: o.recommendation || '',
    confidence_score: num(o.confidence_score),
    evidence: readable(o.evidence),
    cost_tokens: num(cost.tokens),
    cost_model: cost.model || '',
    cost_usd: num(cost.usd_estimate),
    alternative: o.alternative || '',
    agent_specific: readable(o.agent_specific),
    agent_specific_json: asText(o.agent_specific),
    generated_at: new Date().toISOString(),
  } });
}
return out;

const insights = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error || j.__error) continue; // skip agent error passthrough items
  const o = j.output ? j.output : j;
  if (o && (o.agent || o.recommendation)) insights.push(o); // only real agent outputs
}
let question = '';
try { question = $('Build Routing').first().json.question || ''; } catch (e) {}
return [{ json: { insightsText: JSON.stringify(insights), insightCount: insights.length, question } }];

const staticData = $getWorkflowStaticData('global');
const TTL_MS = 24 * 60 * 60 * 1000; // cache golden dataset for 24h
const now = Date.now();
const cache = staticData.goldenCache;
const prep = $('Prepare Eval').first().json || {};
let cached = false;
let goldenText = '[]';
let goldenRowCount = 0;
if (cache && cache.goldenText && cache.cachedAt && (now - cache.cachedAt) < TTL_MS) {
  cached = true;
  goldenText = cache.goldenText;
  goldenRowCount = cache.goldenRowCount || 0;
}
return [{ json: {
  cached,
  goldenText,
  goldenRowCount,
  insightsText: prep.insightsText || '[]',
  question: prep.question || '',
} }];

