const asText = (v) => (typeof v === 'string' ? v : JSON.stringify(v));

// Load the actual agent outputs so each eval row also carries the agent's overall output.
let insights = [];
try { insights = JSON.parse($('Prepare Eval').first().json.insightsText || '[]'); } catch (e) {}
let question = '';
try { question = $('Prepare Eval').first().json.question || ''; } catch (e) {}
const byAgent = {};
for (const ins of insights) { if (ins && ins.agent) byAgent[ins.agent] = ins; }

const attachAgentOutput = (row, name) => {
  const a = byAgent[name] || {};
  row.agent_recommendation = a.recommendation || '';
  row.agent_evidence = asText(a.evidence != null ? a.evidence : '');
  row.agent_confidence_score = a.confidence_score;
  row.agent_cost_of_insight = asText(a.cost_of_insight != null ? a.cost_of_insight : '');
  row.agent_alternative = asText(a.alternative != null ? a.alternative : '');
  row.agent_specific = asText(a.agent_specific != null ? a.agent_specific : '');
  row.agent_full_output = Object.keys(a).length ? asText(a) : '';
  return row;
};

const out = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error || j.__error) continue; // skip eval error passthrough items
  const o = j.output ? j.output : j;
  if (!o || (!o.overall_status && !o.quality_gate_decision && !Array.isArray(o.results))) continue; // only real eval outputs
  const results = Array.isArray(o.results) ? o.results : [];
  const base = {
    overall_status: o.overall_status || '',
    quality_gate_decision: o.quality_gate_decision || '',
    question: question,
    generated_at: new Date().toISOString(),
    execution_id: $execution.id,
  };
  if (results.length === 0) {
    out.push({ json: attachAgentOutput(Object.assign({}, base, { agent_name: '', schema_valid: '', actionability: '', grounding: '', hallucination_risk: '', status: '', issues: '', summary: asText(o) }), '') });
  } else {
    for (const r of results) {
      const s = r.scores || {};
      out.push({ json: attachAgentOutput(Object.assign({}, base, {
        agent_name: r.agent_name || '',
        schema_valid: r.schema_valid,
        actionability: s.actionability,
        grounding: s.grounding,
        hallucination_risk: s.hallucination_risk,
        status: r.status || '',
        issues: asText(r.issues),
        summary: asText(r.summary),
      }), r.agent_name || '') });
    }
  }
}
return out;

const evalOut = ($json && $json.output) ? $json.output : ($json || {});
let insights = [];
try { insights = JSON.parse($('Prepare Eval').first().json.insightsText || '[]'); } catch (e) {}
const LF = String.fromCharCode(10);
const lines = [];
lines.push('HireFast AI — Hiring Insights');
for (const ins of insights) {
  if (!ins) continue;
  lines.push('');
  lines.push('• ' + (ins.agent || 'Agent') + ': ' + (ins.recommendation || ''));
  if (ins.confidence_score != null) lines.push('  confidence: ' + ins.confidence_score);
}
lines.push('');
lines.push('Quality gate: ' + (evalOut.overall_status || 'n/a') + ' — decision: ' + (evalOut.quality_gate_decision || 'n/a'));
return [{ json: { chat_message: lines.join(LF), overall_status: evalOut.overall_status || '', quality_gate_decision: evalOut.quality_gate_decision || '' } }];

const rows = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (Object.keys(j).length === 0) continue;
  rows.push(j);
}
const prep = $('Prepare Eval').first().json;
const goldenText = JSON.stringify(rows.slice(0, 500));
const goldenRowCount = rows.length;
// Store parsed golden dataset in cross-execution cache for reuse.
const staticData = $getWorkflowStaticData('global');
staticData.goldenCache = { goldenText, goldenRowCount, cachedAt: Date.now() };
return [{ json: {
  goldenText,
  goldenRowCount,
  insightsText: prep.insightsText || '[]',
  question: prep.question || '',
} }];
